@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ---------- View transitions ---------- */

/* Directional page slides: forward navigation sweeps left
   (home exits left, detail enters from the right); backward
   navigation sweeps right. */
::view-transition-new(.page-slide-in-from-right) {
  animation: 300ms cubic-bezier(0.22, 1, 0.36, 1) both vt-slide-in-from-right;
}

::view-transition-old(.page-slide-out-to-left) {
  animation: 300ms cubic-bezier(0.22, 1, 0.36, 1) both vt-slide-out-to-left;
}

::view-transition-new(.page-slide-in-from-left) {
  animation: 300ms cubic-bezier(0.22, 1, 0.36, 1) both vt-slide-in-from-left;
}

::view-transition-old(.page-slide-out-to-right) {
  animation: 300ms cubic-bezier(0.22, 1, 0.36, 1) both vt-slide-out-to-right;
}

/* Shared product image morphing between grid thumbnail and detail hero */
::view-transition-group(.product-image-morph) {
  animation-duration: 300ms;
  animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
}

::view-transition-old(.product-image-morph),
::view-transition-new(.product-image-morph) {
  height: 100%;
  width: 100%;
}

/* Suspense: skeleton fades out, real content fades in */
::view-transition-old(.suspense-fade-out) {
  animation: 150ms ease-in both vt-fade-out;
}

::view-transition-new(.suspense-fade-in) {
  animation: 250ms ease-out both vt-fade-in;
}

@keyframes vt-slide-in-from-right {
  from {
    opacity: 0;
    transform: translateX(64px);
  }
}

@keyframes vt-slide-out-to-left {
  to {
    opacity: 0;
    transform: translateX(-64px);
  }
}

@keyframes vt-slide-in-from-left {
  from {
    opacity: 0;
    transform: translateX(-64px);
  }
}

@keyframes vt-slide-out-to-right {
  to {
    opacity: 0;
    transform: translateX(64px);
  }
}

@keyframes vt-fade-out {
  to {
    opacity: 0;
  }
}

@keyframes vt-fade-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-image-pair(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

